<template>
  <label class="ln-select-field"><span v-if="label" class="ln-select-field__label">{{label}}</span><LnPopover align="start" @update:open="onOpen">
    <template #trigger><button class="ln-select__trigger ln-focus-ring" type="button" :disabled="disabled"><LnOptionIcon v-if="hasOptionIcon(selected)" :value="selected?.value" :label="selected?.label" :icon="selected?.icon" :color="selected?.color"/><span :class="{'is-placeholder':!selected}">{{selected?.label||placeholder}}</span><LnIcon class="ln-select__chevron" name="chevron-down"/></button></template>
    <template #default="{close}"><div class="ln-select__panel"><input v-if="searchable" ref="searchInput" v-model="query" class="ln-select__search" placeholder="搜索…"/><div class="ln-select__options"><button v-if="clearable && modelValue" class="ln-select__option is-clear" type="button" @click="clear(close)"><LnIcon name="close"/><span><b>清除选择</b></span></button><button v-for="option in filtered" :key="option.value" class="ln-select__option" :class="{'is-selected':option.value===modelValue}" type="button" :disabled="option.disabled" @click="choose(option,close)"><LnOptionIcon v-if="hasOptionIcon(option)" :value="option.value" :label="option.label" :icon="option.icon" :color="option.color"/><span><b>{{option.label}}</b><small v-if="option.description">{{option.description}}</small></span><i v-if="option.value===modelValue" class="ln-select__check" aria-label="已选择"/></button><div v-if="!filtered.length" class="ln-select__empty">没有匹配项</div></div></div></template>
  </LnPopover></label>
</template>
<script setup lang="ts">
import { computed,nextTick,ref } from 'vue'; import LnPopover from './LnPopover.vue'; import LnIcon from './LnIcon.vue'; import LnOptionIcon from './LnOptionIcon.vue'; import type {LnOption} from './types'
const props=withDefaults(defineProps<{modelValue?:string;options:LnOption[];label?:string;placeholder?:string;searchable?:boolean;disabled?:boolean;clearable?:boolean}>(),{placeholder:'请选择'})
const emit=defineEmits<{(e:'update:modelValue',value:string):void;(e:'change',option?:LnOption):void}>(); const query=ref('');const searchInput=ref<HTMLInputElement>();const selected=computed(()=>props.options.find(o=>o.value===props.modelValue));const filtered=computed(()=>{const q=query.value.trim().toLowerCase();return q?props.options.filter(o=>(o.label+o.description).toLowerCase().includes(q)):props.options})
function hasOptionIcon(option?:LnOption){return !!(option?.color||option?.icon||/P[0-3]/i.test(`${option?.value||''} ${option?.label||''}`))}
function choose(option:LnOption,close:()=>void){if(option.disabled)return;emit('update:modelValue',option.value);emit('change',option);close()};function clear(close:()=>void){emit('update:modelValue','');emit('change');close()}function onOpen(open:boolean){if(open&&props.searchable)nextTick(()=>searchInput.value?.focus());else query.value=''}
</script>
<style scoped lang="scss">
.ln-select-field{display:grid;gap:6px;font-family:var(--ln-font)}.ln-select-field__label{font-size:13px;font-weight:540}.ln-select__trigger{min-width:150px;height:var(--ln-control-md);padding:0 9px;display:flex;align-items:center;gap:7px;border:1px solid var(--ln-border-strong);border-radius:var(--ln-radius-md);background:var(--ln-surface);color:var(--ln-text);font:13px var(--ln-font);cursor:pointer;&:hover{background:var(--ln-surface-hover)}.is-placeholder{color:var(--ln-text-tertiary)}}.ln-select__chevron{width:14px;height:14px;margin-left:auto;color:var(--ln-icon-muted)}.ln-select__panel{width:250px}.ln-select__search{width:100%;height:32px;margin-bottom:5px;padding:0 8px;border:1px solid var(--ln-border);border-radius:5px;outline:0;font:13px var(--ln-font);&:focus{border-color:var(--ln-accent)}}.ln-select__options{max-height:250px;overflow:auto;display:grid;gap:2px}.ln-select__option{min-height:36px;padding:6px 8px;display:flex;align-items:center;gap:8px;border:0;border-radius:5px;background:transparent;color:var(--ln-text);text-align:left;cursor:pointer;&:hover,&.is-selected{background:var(--ln-surface-hover)}&:disabled{opacity:.4}&.is-clear{margin-bottom:3px;border-bottom:1px solid var(--ln-border);border-radius:0;color:var(--ln-text-secondary)}span:nth-child(2){display:grid;gap:2px}b{font-size:13px;font-weight:540}small{color:var(--ln-text-tertiary);font-size:11px}.ln-select__check{width:8px;height:5px;margin-left:auto;border-left:1.5px solid var(--ln-accent);border-bottom:1.5px solid var(--ln-accent);transform:translateY(-1px) rotate(-45deg)}}.ln-select__empty{padding:18px;text-align:center;color:var(--ln-text-tertiary);font-size:12px}
</style>
